package com.madlava.reporting;
import static org.junit.jupiter.api.Assertions.*; import com.madlava.core.FeatureState; import java.time.Instant; import java.util.Map; import org.junit.jupiter.api.Test;
class JsonEncoderTest { @Test void emitsSchemaV3Envelope(){String json=JsonEncoder.encode(new Snapshot("0.1.0-dev.1","abc",1,0,Instant.EPOCH,false,Map.of("selfObservability",FeatureState.RUNNING)));assertTrue(json.startsWith("{\"schemaVersion\":3"));assertTrue(json.contains("\"configurationHash\":\"abc\""));assertTrue(json.contains("\"state\":\"RUNNING\""));assertFalse(json.contains("NaN"));} @Test void escapesControlCharacters(){assertEquals("a\\n\\\"b",JsonEncoder.escape("a\n\"b"));} @Test void featureDataEncodingNeverCallsArbitraryToStringAndNeverEmitsNonFiniteNumbers(){Object hostile=new Object(){@Override public String toString(){throw new AssertionError("must not be called");}};String json=JsonEncoder.encode(new Snapshot("0.1.0-dev.1","abc",1,0,Instant.EPOCH,false,Map.of("x",FeatureState.RUNNING),Map.of("x",Map.of("hostile",hostile,"nan",Double.NaN))));assertTrue(json.contains("<com.madlava.reporting.JsonEncoderTest$"));assertTrue(json.contains("\"nan\":null"));}}
